text:
--tab-min-height: 33px;
--lwt-tabs-border-color: var(--sidebar-border);
--tabs-tabbar-border-size: 1px;
--toolbar-button-hover-background-color: color-mix(in srgb, currentColor 10%, transparent);
--toolbar-button-hover-border-color: color-mix(in srgb, currentColor 30%, transparent);
--toolbar-button-hover-checked-color: color-mix(in srgb, currentColor 20%, transparent);
--toolbar-button-active-background-color: color-mix(in srgb, currentColor 20%, transparent);
--toolbar-button-active-border-color: color-mix(in srgb, currentColor 40%, transparent);
--toolbarbutton-icon-fill: currentColor;
--toolbarbutton-icon-fill-opacity: 0.85;
--toolbarbutton-background-color-hover: light-dark(
  var(--lwt-toolbarbutton-hover-background, rgba(0, 0, 0, 0.05)),
  var(--lwt-toolbarbutton-hover-background, rgba(255, 255, 255, 0.25))
);
--toolbarbutton-hover-bordercolor: light-dark(
  var(--lwt-toolbarbutton-hover-background, rgba(0, 0, 0, 0.25)),
  var(--lwt-toolbarbutton-hover-background, rgba(255, 255, 255, 0.5))
);
--toolbarbutton-header-bordercolor: light-dark(
  var(--lwt-toolbarbutton-hover-background, rgba(0, 0, 0, 0.25)),
  var(--lwt-toolbarbutton-hover-background, rgba(255, 255, 255, 0.25))
);
--toolbarbutton-hover-boxshadow: none;
--toolbarbutton-background-color-active: light-dark(
  var(--lwt-toolbarbutton-active-background, rgba(0, 0, 0, 0.1)),
  var(--lwt-toolbarbutton-active-background, rgba(255, 255, 255, 0.4))
);
--toolbarbutton-active-bordercolor: light-dark(
  var(--lwt-toolbarbutton-active-background, rgba(0, 0, 0, 0.3)),
  var(--lwt-toolbarbutton-active-background, rgba(255, 255, 255, 0.7))
);
--toolbarbutton-default-active-boxshadow: rgba(0, 0, 0, 0.1) inset, 0 0 1px rgba(0, 0, 0, 0.3);
--toolbarbutton-active-boxshadow: light-dark(0 1px 1px var(--lwt-toolbarbutton-active-background, var(--toolbarbutton-default-active-boxshadow)) inset, none);
